        ["start.report.working"] = ("Собираем отчёт…", "Making the report…"),
        ["start.report.done"] = ("Отчёт сохранён на рабочий стол: {0}. Отправьте этот файл в поддержку.", "Report saved to the Desktop: {0}. Send this file to support."),
